/* WebXR transient-pointer sources exist only during a select gesture, often without XRHand. */
(()=>{const T=AFRAME.THREE;
AFRAME.registerComponent('xr-transient-input',{
 init(){this.active=new Map();this.completed=new WeakSet();this.counter=0;this.enter=()=>this.bind();this.exit=()=>{for(const input of [...this.active.keys()])this.finish(input);this.completed=new WeakSet()};this.el.addEventListener('enter-vr',this.enter);this.el.addEventListener('exit-vr',this.exit);window.addEventListener('blur',this.exit);this.bind()},
 bind(){const session=this.el.renderer?.xr?.getSession?.();if(session===this.session)return;this.exit();this.cleanup?.();this.session=session;if(!session)return;const start=e=>{if(e.inputSource?.targetRayMode==='transient-pointer')this.start(e.inputSource,e.frame)},end=e=>{if(e.inputSource?.targetRayMode==='transient-pointer')this.finish(e.inputSource,e.frame)},select=e=>{if(e.inputSource?.targetRayMode==='transient-pointer'&&!this.active.has(e.inputSource)&&!this.completed.has(e.inputSource)){this.start(e.inputSource,e.frame);this.finish(e.inputSource,e.frame)}};session.addEventListener('selectstart',start);session.addEventListener('selectend',end);session.addEventListener('select',select);this.cleanup=()=>{session.removeEventListener('selectstart',start);session.removeEventListener('selectend',end);session.removeEventListener('select',select)}},
 pose(state,frame){const reference=this.el.renderer?.xr?.getReferenceSpace?.();if(!frame||!reference)return false;let target,grip;try{target=frame.getPose(state.input.targetRaySpace,reference);grip=state.input.gripSpace?frame.getPose(state.input.gripSpace,reference):target}catch{return false}if(!target)return false;const parent=state.source.object3D.parent;parent.updateWorldMatrix(true,false);const matrix=new T.Matrix4().fromArray(target.transform.matrix).premultiply(parent.matrixWorld);state.ray=new T.Ray(new T.Vector3().setFromMatrixPosition(matrix),new T.Vector3(0,0,-1).transformDirection(matrix));if(grip){const local=new T.Matrix4().fromArray(grip.transform.matrix);local.decompose(state.source.object3D.position,state.source.object3D.quaternion,state.source.object3D.scale)}else{state.source.object3D.position.copy(parent.worldToLocal(state.ray.origin.clone()))}state.source.object3D.updateWorldMatrix(true,false);state.point=state.source.object3D.getWorldPosition(new T.Vector3());state.last=performance.now();return true},
 hit(ray){let best;const caster=new T.Raycaster(ray.origin,ray.direction,0,20);for(const el of this.el.querySelectorAll('.interactive')){if(!el.hasAttribute?.('data-nearby-place')&&el.closest?.('#mapRoot,#planet,#pins,#lens,[musical-guitar],[folding-portal]'))continue;let visible=true;for(let o=el.object3D;o;o=o.parent)if(!o.visible)visible=false;for(let o=el.__panelOwner?.object3D;o;o=o.parent)if(!o.visible)visible=false;if(!visible)continue;el.object3D.updateWorldMatrix(true,true);const intersection=caster.intersectObject(el.object3D,true)[0],hit=intersection?{el,intersection}:null;if(window.GlobiquestPanelInput?.better?window.GlobiquestPanelInput.better(hit,best):hit&&(!best||intersection.distance<best.intersection.distance))best=hit}return best},
 emit(state,hit,type){hit?.el.emit(type,{cursorEl:state.source,intersection:hit.intersection,inputSource:'transient-pointer'},true)},
 start(input,frame){if(this.active.has(input))return;this.completed.delete(input);const object=new T.Group(),parent=document.getElementById('rig')?.object3D||this.el.object3D;parent.add(object);const state={input,source:{id:'transient-pointer-'+(++this.counter),object3D:object,components:{}},last:performance.now()};state.source.components['spatial-hand-ui']={readRay:()=>state.ray,candidate:()=>null};state.source.components.raycaster={getIntersection:el=>state.current?.el===el?state.current.intersection:null,raycaster:{}};if(!this.pose(state,frame)){object.removeFromParent();return}state.source.components.raycaster.raycaster.ray=state.ray;this.active.set(input,state);const hit=state.current=this.hit(state.ray),region=window.GlobiquestPanelInput?.region(hit);window.GlobiquestPanelInput?.hover(hit);const dragger=window.globiquest.panelDraggerFor?.(hit?.el);if(hit&&(region?.drag||hit.el.getAttribute?.('data-panel-grip')==='true')&&dragger){if(dragger.start(state.source,parent.worldToLocal(state.point.clone()),hit.el))state.dragger=dragger;return}if(hit){state.pressed=hit;this.emit(state,hit,'mousedown');state.onPress=hit.el.getAttribute?.('data-activate-on-press')==='true';if(state.onPress)this.emit(state,hit,'click');return}if(window.globiquest.artPlay?.airActive&&window.globiquest.artPlay.start(state.source,state.point,'transient'))return;const globe=document.getElementById('mapRoot')?.components?.['bimanual-globe'];if(globe?.start(state.source,'pinch',state.point))state.globe=globe},
 move(state,frame){if(!this.pose(state,frame))return;state.source.components.raycaster.raycaster.ray=state.ray;if(window.globiquest.artPlay?.isSource(state.source))window.globiquest.artPlay.move(state.source,state.point);if(state.dragger)state.dragger.move(state.source,state.source.object3D.parent.worldToLocal(state.point.clone()));const patch=window.globiquest.globePatch;if(patch?.source===state.source)patch.move(state.source,state.point);const grab=state.globe?.grabs.get(state.source);if(grab){grab.point.copy(state.point);grab.last=performance.now()}if(state.pressed){state.current=this.hit(state.ray);this.emit(state,state.current,'mousemove')}},
 finish(input,frame){const state=this.active.get(input);if(!state)return;if(frame)this.move(state,frame);window.globiquest.artPlay?.end(state.source);state.dragger?.end();if(window.globiquest.globePatch?.source===state.source)window.globiquest.globePatch.end(state.source);state.globe?.end(state.source);if(state.pressed){this.emit(state,state.pressed,'mouseup');if(!state.onPress&&state.current?.el===state.pressed.el)this.emit(state,state.pressed,'click')}window.GlobiquestPanelInput?.release(state.source);state.source.object3D.removeFromParent();this.active.delete(input);this.completed.add(input)},
 tick(){this.bind();const frame=this.el.renderer?.xr?.getFrame?.();for(const state of [...this.active.values()]){this.move(state,frame);if(performance.now()-state.last>1000)this.finish(state.input)}},
 remove(){this.exit();this.cleanup?.();this.el.removeEventListener('enter-vr',this.enter);this.el.removeEventListener('exit-vr',this.exit);window.removeEventListener('blur',this.exit)}
});const setup=()=>scene.setAttribute('xr-transient-input','');if(scene.hasLoaded)setup();else scene.addEventListener('loaded',setup,{once:true});})();
